const ZERO: Point = {x: 0, y: 0};

const DIRECTION_VECTORS: Partial<Record<PanDirection, Point>> = {
  left: {x: -1, y: 0},
  right: {x: 1, y: 0},
  up: {x: 0, y: -1},
  down: {x: 0, y: 1},
