      this.tapStarts.clear();
      this.tapLifts.clear();
      this.maxTouchesThisTap = 0;
      this.clearTimer();
      if (Number.isFinite(this.maximumTapDuration)) {
        this.setTimer(event.time + this.maximumTapDuration, () => {
          this.setState('failed');
