  offsetBy(dx: number, dy: number): void {
    const shift = (sample: TouchSample): TouchSample => ({
      ...sample,
      x: sample.x + dx,
      y: sample.y + dy,
    });
    this.newest = this.newest == null ? null : shift(this.newest);
    this.moved = this.moved.map(shift);
