  touches: Iterable<GestureTouch>,
  excluding?: ReadonlySet<number>,
): Point {
  let x = 0;
  let y = 0;
  let count = 0;
  for (const touch of touches) {
    if (excluding?.has(touch.id)) {
      continue;
    }
    x += touch.x;
    y += touch.y;
    count += 1;
  }
  return count === 0 ? {x: 0, y: 0} : {x: x / count, y: y / count};
