  const y = style.overscrollBehaviorY;
  if (x !== '' && y !== '' && x != null && y != null) {
    return [x, y];
  }
  const [first = 'auto', second = first] = (
    style.getPropertyValue('overscroll-behavior') || 'auto'
  )
    .trim()
    .split(/\s+/);
