  for (const part of parts) {
    if (part === 'auto') {
      ALL_PANS.forEach(token => tokens.add(token));
      tokens.add('double-tap-zoom');
    } else if (part === 'manipulation') {
      ALL_PANS.forEach(token => tokens.add(token));
    } else if (part === 'pan-x') {
      tokens.add('pan-left').add('pan-right');
    } else if (part === 'pan-y') {
      tokens.add('pan-up').add('pan-down');
