export function unmarkTouchAction(element: Element): void {
  element.removeAttribute(TOUCH_ACTION_ATTRIBUTE);
  const root = markedRoots.get(element);
  if (root == null) {
    return;
  }
  markedRoots.delete(element);
  releaseMark(element, root);
}

