    createActionGroupTracker(() => ({
      roots: () => [ref.current],
      itemSelector: optionsRef.current.itemSelector,
      isItem: optionsRef.current.isItem,
      highlightExpansion:
        pointerRef.current === 'touch'
          ? optionsRef.current.highlightExpansion
          : 0,
