    selection.setBaseAndExtent(
      only.startContainer,
      only.startOffset,
      only.endContainer,
      only.endOffset,
    );
    return;
  }
  selection.removeAllRanges();
  for (const range of ranges) {
    const copy = range.startContainer.ownerDocument?.createRange();
    if (copy == null) {
      continue;
